#!/system/bin/sh
# ============================================================
# patch-lan-proxy.sh — DSHA 局域网反向代理核心增量补丁
# 
# 职责：
# 1. 为已有底包老用户增量注入高性能局域网反向代理实体 (dsha-lan-proxy.js)；
# 2. 独立初始化局域网通信 Token (.lan_token)，与底层设备桥 .bridge_token 解耦；
# 3. 配置权限与启动环境，确保 0.0.0.0:3081 局域网监听即刷即用。
# ============================================================
set -eu

ROOTFS="${1:-/data/adb/dsha/rootfs}"
DATA_DIR="${2:-/data/adb/dsha}"

echo "==> [增量补丁] 正在为现有系统注入局域网代理 (lan-proxy) 核心组件..."

if [ ! -d "$ROOTFS/root" ]; then
    echo "⚠️ 错误: 未检测到有效的 rootfs 目录 ($ROOTFS)，跳过补丁应用。"
    exit 1
fi

DSH_DIR="$ROOTFS/root/.dsh"
mkdir -p "$DSH_DIR"
PROXY_TARGET="$DSH_DIR/dsha-lan-proxy.js"

# 1. 优先从模块外部 rootfs-overlay 提取，未找到则使用内嵌 Base64 还原
SRC_OVERLAY="$(dirname "$0")/../rootfs-overlay/root/.dsh/dsha-lan-proxy.js"
if [ -f "$SRC_OVERLAY" ]; then
    cp -f "$SRC_OVERLAY" "$PROXY_TARGET"
    echo "  ✓ 从模块 overlay 镜像同步: dsha-lan-proxy.js"
else
    cat << \EOF_B64_LAN_PROXY | base64 -d > "$PROXY_TARGET"

EOF_B64_LAN_PROXY
    echo "  ✓ 通过内嵌实体释放核心代理组件: dsha-lan-proxy.js"
fi
chmod 755 "$PROXY_TARGET"

# 2. 初始化局域网独立 Token 文件 (.lan_token)，权限 666
LAN_TOKEN_FILE="$DSH_DIR/.lan_token"
BRIDGE_TOKEN_FILE="$DSH_DIR/.bridge_token"
if [ ! -s "$LAN_TOKEN_FILE" ]; then
    if [ -s "$BRIDGE_TOKEN_FILE" ]; then
        cp -f "$BRIDGE_TOKEN_FILE" "$LAN_TOKEN_FILE"
        echo "  ✓ 继承现有设备 Token 初始化 .lan_token"
    else
        TOK=$(tr -dc "a-zA-Z0-9" < /dev/urandom 2>/dev/null | head -c 32 || echo "dsha_lan_$(date +%s)")
        echo -n "$TOK" > "$LAN_TOKEN_FILE"
        echo "  ✓ 自动生成全新 32 位安全 .lan_token"
    fi
fi
chmod 666 "$LAN_TOKEN_FILE" 2>/dev/null || true
[ -f "$BRIDGE_TOKEN_FILE" ] && chmod 666 "$BRIDGE_TOKEN_FILE" 2>/dev/null || true

# 3. 确保宿主控制脚本具备执行权限
[ -f "$DATA_DIR/scripts/lan-proxy.sh" ] && chmod 755 "$DATA_DIR/scripts/lan-proxy.sh" 2>/dev/null || true

echo "✓ 局域网反向代理增量补丁部署成功！(监听 0.0.0.0:3081 -> 127.0.0.1:3080)"
exit 0
